(()=>{'use strict';
const root=document.querySelector('#app'),KEY='mission-method-individual-giving-v1';
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const iso=()=>new Date().toISOString().slice(0,10);
const shift=(date,n)=>{const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>d?new Date(`${d}T12:00:00`).toLocaleDateString('en',{day:'numeric',month:'short',year:'numeric'}):'—';
const month=d=>String(d||'').slice(0,7),year=d=>String(d||'').slice(0,4);
const money=(n,c='USD')=>new Intl.NumberFormat('en',{style:'currency',currency:/^[A-Z]{3}$/.test(c)?c:'USD',maximumFractionDigits:0}).format(Number(n)||0);
const safeUrl=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const opt=(arr,current)=>arr.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(l)}</option>`).join('');
const field=(label,name,v='',type='text',attr='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(v)}" ${attr}></label>`;
const area=(label,name,v='')=>`<label class="field full">${label}<textarea name="${name}">${esc(v)}</textarea></label>`;
const sel=(label,name,values,v)=>`<label class="field">${label}<select name="${name}">${opt(values.map(x=>Array.isArray(x)?x:[x,x]),v)}</select></label>`;
const tip=x=>`<span class="tip"><button type="button" aria-label="More information">i</button><span>${esc(x)}</span></span>`;
const pill=s=>`<span class="pill ${['Failed payment','Cancelled','At risk','Delayed','Overdue'].includes(s)?'warn':['Paused','Planned','Not contacted'].includes(s)?'dim':''}">${esc(s)}</span>`;
const frequencies=['Monthly','Quarterly','Yearly'];
const recurringStates=['Active','Paused','Failed payment','Upgraded','Downgraded','Cancelled'];
const actionStates=['Planned','In progress','Completed','Delayed'];
const reactivationStates=['Not contacted','Contact planned','Contacted','Reactivated','Not interested'];
const strategySeeds={
 Gain:[
  ['Donation landing page','A clear page showing a concrete outcome and a short, usable payment journey.','New visitors','Draft impact examples; test the form; publish and measure completion.','An impact story with one clear invitation.','Landing-page conversion','Medium','High'],
  ['Social and seasonal campaigns','Timed stories and invitations can introduce new supporters to the mission.','Followers and first-time donors','Choose an audience; set a target; publish a sequence; review results.','Join this campaign and see the difference your gift makes.','First-time donors per campaign','Medium','High'],
  ['Newsletter to first donation','A welcome series turns interested readers into informed supporters.','Newsletter subscribers','Gain consent; send useful stories; invite a first gift.','Here is what your support could make possible.','First-gift conversion','Low','Medium'],
  ['Peer and business partnerships','Trusted advocates can extend reach beyond existing channels.','Ambassadors and ethical businesses','Identify partners; agree a shared ask; provide materials; follow up.','Invite your community to join this effort.','Referrals and gifts generated','Medium','Medium']
 ],
 Retain:[
  ['Personal thank-you','A prompt, specific thank-you recognises the donor as a person.','Every donor','Confirm the gift; personalise a message; record contact.','Thank you for making this work possible.','Thank-yous within 48 hours','Low','High'],
  ['Welcome and impact updates','Regular evidence helps donors understand the value of staying involved.','New and recurring donors','Send welcome steps; share outcomes; ask for preferences.','Here is what your continued support enabled.','Retention rate','Medium','High'],
  ['Payment-failure recovery','A respectful follow-up can prevent an accidental lapse.','Donors with failed payments','Check payment status; contact privately; offer a secure update route.','It looks like your gift did not complete. Would you like help?','Recovered payments','Low','High'],
  ['Feedback and preferences','Listening improves relevance and avoids unwanted contact.','All engaged supporters','Ask what matters; save preferences; adjust future outreach.','What would you like to hear more about?','Preference updates','Low','Medium']
 ],
 Maximise:[
  ['Thoughtful recurring upgrade','An informed invitation may increase support without pressure.','Loyal recurring donors','Review history; choose a good moment; explain additional impact; honour no.','Would a different giving level work for you?','Upgrade acceptance','Low','Medium'],
  ['Major supporter pathway','Closer stewardship can deepen a values-aligned relationship.','High-value supporters','Assign an owner; listen to interests; share a tailored opportunity.','Could we discuss what matters most to you?','Major gifts received','High','Medium'],
  ['Matching and campaign asks','A relevant time-bound ask can amplify an existing relationship.','Engaged supporters','Identify a match or campaign; explain the impact; follow up.','Your gift could go further in this campaign.','Campaign value','Medium','Medium'],
  ['Re-engagement and ambassadors','Former donors can choose to reconnect or share the mission.','Previous donors and advocates','Thank for past support; share progress; offer ways to participate.','Thank you for being part of the journey.','Reactivated donors','Low','Medium']
 ]
};
const automationSeeds=[
 ['Gift received','Immediately','Thank-you and receipt','Send a specific thank-you and confirm receipt details.'],
 ['New recurring donor','Within 2 days','Welcome journey','Explain impact updates and how to change preferences.'],
 ['First-time donor','After 30 days','Impact update','Share an outcome and invite continued engagement.'],
 ['Payment failed','Within 3 days','Payment follow-up','Offer a secure way to update the payment method.'],
 ['Recurring anniversary','On anniversary','Milestone note','Thank the supporter for continued involvement.'],
 ['Donor at risk','After lapse threshold','Reactivation','Thank for past giving and offer a no-pressure way to reconnect.']
];
const blank=()=>({version:1,meta:{organisation:'',currency:'USD',monthlyTarget:2000,annualTarget:24000,lapseMonths:12,stewardshipDays:90,preparedBy:''},donors:[],gifts:[],activities:[],campaigns:[],actions:[],strategies:Object.entries(strategySeeds).flatMap(([pillar,rows])=>rows.map(([title,why,audience,steps,message,kpi,effort,priority])=>({id:uid(),pillar,title,what:title,why,audience,steps,message,kpi,effort,priority,actionId:'',active:true}))),automations:automationSeeds.map(([trigger,delay,title,message])=>({id:uid(),trigger,delay,title,message,owner:'Fundraising lead',status:'Draft',lastReviewed:''}))});
function example(){const db=blank();db.meta.organisation='Example Community Fund';const donor=(name,country,joined,amount,frequency,status,interests,owner)=>({id:uid(),name,email:'',country,joined,amount,currency:'USD',frequency,paymentMethod:'Card',paymentStatus:status==='Failed payment'?'Failed':'OK',status,interests,owner,consent:'Email updates',preferences:'Quarterly impact update',notes:'Fictional sample record',lastContact:shift(iso(),-25),nextExpected:shift(iso(),20),cancellationReason:'',reactivation:'Not contacted',potentialRecurring:false});
 db.donors=[donor('Amina Bello','Kenya',shift(iso(),-390),25,'Monthly','Active','Education','Maya'),donor('Ravi Sen','India',shift(iso(),-225),40,'Monthly','Active','Climate','Maya'),donor('Isabel Cruz','Philippines',shift(iso(),-460),15,'Monthly','Failed payment','Health','Jo'),donor('Noah Kim','Canada',shift(iso(),-510),50,'Monthly','Cancelled','Education','Jo'),donor('Leila Osman','UK',shift(iso(),-60),0,'','One-time','Women’s leadership','Maya'),donor('Theo Martin','France',shift(iso(),-190),0,'','One-time','Climate','Jo')];
 db.donors[3].cancellationReason='Changed circumstances';db.donors[4].potentialRecurring=true;
 const gift=(i,days,amount,type,campaign='')=>({id:uid(),donorId:db.donors[i].id,date:shift(iso(),days),amount,currency:'USD',type,campaign,method:'Card',receipt:'Sent'});
 db.gifts=[gift(0,-10,25,'Recurring'),gift(0,-40,25,'Recurring'),gift(0,-70,25,'Recurring'),gift(1,-13,40,'Recurring'),gift(1,-44,40,'Recurring'),gift(2,-47,15,'Recurring'),gift(3,-370,50,'Recurring'),gift(4,-7,100,'One-time','Spring appeal'),gift(5,-95,75,'One-time','Community event'),gift(4,-200,30,'One-time','Winter appeal')];
 db.campaigns=[{id:uid(),name:'Spring appeal',start:shift(iso(),-25),end:shift(iso(),35),goal:1200,currency:'USD',status:'Active'},{id:uid(),name:'Community event',start:shift(iso(),-110),end:shift(iso(),-80),goal:600,currency:'USD',status:'Completed'}];
 db.activities=[{id:uid(),donorId:db.donors[4].id,date:shift(iso(),-6),type:'Thank-you',note:'Sent a personal thank-you for the Spring appeal.',owner:'Maya'}];
 db.actions=[{id:uid(),objective:'Gain first-time supporters',activity:'Publish a Spring appeal story and donation page',rationale:'The audience needs a concrete invitation.',segment:'Newsletter subscribers',owner:'Maya',start:shift(iso(),-20),due:shift(iso(),15),budget:200,kpi:'20 first-time gifts',status:'In progress',progress:55,evidence:'',risk:'Low reach',nextSteps:'Test the page and schedule follow-up.',campaignId:db.campaigns[0].id,priority:'High'},{id:uid(),objective:'Retain existing supporters',activity:'Send a personal impact update',rationale:'Supporters should see what their gifts enable.',segment:'Active recurring donors',owner:'Jo',start:iso(),due:shift(iso(),14),budget:0,kpi:'All active recurring donors contacted',status:'Planned',progress:0,evidence:'',risk:'Outdated contact preferences',nextSteps:'Check consent first.',campaignId:'',priority:'High'}];
 return db}
let db;try{db=JSON.parse(localStorage.getItem(KEY))||example()}catch{db=example()}if(!db?.meta||!Array.isArray(db.donors)||!Array.isArray(db.gifts))db=example();
let tab='Dashboard',modal='',notice='',selectedDonor='',period='Month',actionView='Table',reportKind='Monthly fundraising',filters={currency:db.meta.currency,country:'All',campaign:'All',type:'All',from:'',to:''};
const donor=id=>db.donors.find(x=>x.id===id),giftsFor=id=>db.gifts.filter(g=>g.donorId===id),lastGift=id=>giftsFor(id).map(g=>g.date).sort().at(-1)||'',totalFor=(id,currency=filters.currency)=>giftsFor(id).filter(g=>g.currency===currency).reduce((n,g)=>n+Number(g.amount||0),0);
const active=()=>db.donors.filter(d=>['Active','Upgraded','Downgraded'].includes(d.status));
const elapsedDays=(a,b)=>Math.round((new Date(`${b}T12:00:00`)-new Date(`${a}T12:00:00`))/86400000);
const lapsed=d=>d.status==='Cancelled'||d.status==='Failed payment'||(lastGift(d.id)&&elapsedDays(lastGift(d.id),iso())>Number(db.meta.lapseMonths||12)*30);
const previous=()=>db.donors.filter(lapsed);
const gifts=()=>db.gifts.filter(g=>(filters.currency==='All'||g.currency===filters.currency)&&(filters.campaign==='All'||g.campaign===filters.campaign)&&(filters.type==='All'||g.type===filters.type)&&(!filters.from||g.date>=filters.from)&&(!filters.to||g.date<=filters.to)&&(filters.country==='All'||donor(g.donorId)?.country===filters.country));
const sum=rows=>rows.reduce((n,g)=>n+Number(g.amount||0),0);
function save(msg='Saved in this browser.'){localStorage.setItem(KEY,JSON.stringify(db));notice=msg;render()}
function download(name,body,type){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
const csv=rows=>'\uFEFF'+rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');
const selectOptions=(arr,current)=>opt(arr.map(x=>Array.isArray(x)?x:[x,x]),current);
function shell(){
 const sections=['Dashboard','Recurring donors','One-time donors','Previous donors','Income','Action plan','Strategies','Journey & automations','Reports'];
 return `<div class="shell"><aside class="sidebar"><a class="brand" href="../../software.html">Mission <em>&</em> Method</a><div class="sidebar-intro">Individual giving<span>Donor management</span></div><nav class="nav" aria-label="Individual giving sections">${sections.map((t,i)=>`<button type="button" data-tab="${t}" class="${tab===t?'active':''}" ${tab===t?'aria-current="page"':''}><span class="nav-index" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span>${t}</span></button>`).join('')}</nav><a class="suite-link" href="../../software.html">← Software Suite</a></aside><div class="workspace"><div class="hero"><span class="eyebrow">Funding & partnerships · interactive preview</span><h1>Individual giving & donor management</h1><p>Understand income, build respectful supporter relationships, plan fundraising actions and take useful reports with you.</p><div class="toolbar"><span class="pill warn">Fictional sample data · local browser only</span><button class="button secondary" data-act="backup">Download backup</button></div></div><main id="main">${notice?`<div class="notice" role="status">${esc(notice)}</div>`:''}${content()}</main><footer class="tiny">Saved in this browser · Export your work regularly · Mission & Method</footer></div></div>${modal}`
}
function content(){return tab==='Dashboard'?dashboard():tab==='Recurring donors'?recurringView():tab==='One-time donors'?oneTimeView():tab==='Previous donors'?previousView():tab==='Income'?incomeView():tab==='Action plan'?actionPlan():tab==='Strategies'?strategiesView():tab==='Journey & automations'?journeyView():reportsView()}
function metric(label,value,detail=''){return `<div class="card"><span class="eyebrow">${esc(label)}</span><div class="metric">${esc(value)}</div><p>${esc(detail)}</p></div>`}
function trend(rows){const months=Array.from({length:12},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-11+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`});const values=months.map(m=>sum(rows.filter(g=>month(g.date)===m))),max=Math.max(1,...values);return `<div class="chart" role="img" aria-label="Monthly income trend: ${months.map((m,i)=>`${m} ${money(values[i],filters.currency)}`).join(', ')}">${months.map((m,i)=>`<div class="column" title="${esc(m)} · ${money(values[i],filters.currency)}"><b>${values[i]?esc(Math.round(values[i])):''}</b><i style="height:${Math.max(3,Math.round(values[i]/max*140))}px"></i>${m.slice(5)}</div>`).join('')}</div>`}
function growthChart(){const months=Array.from({length:12},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-11+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}),values=months.map(m=>db.donors.filter(d=>month(d.joined)===m).length),max=Math.max(1,...values);return `<div class="chart" role="img" aria-label="New donors by month: ${months.map((m,i)=>`${m} ${values[i]}`).join(', ')}">${months.map((m,i)=>`<div class="column"><b>${values[i]||''}</b><i style="height:${Math.max(3,Math.round(values[i]/max*140))}px"></i>${m.slice(5)}</div>`).join('')}</div>`}
function dashboard(){const c=filters.currency==='All'?db.meta.currency:filters.currency,rows=db.gifts.filter(g=>g.currency===c),m=month(iso()),y=year(iso()),thisYear=rows.filter(g=>year(g.date)===y),yearBefore=String(Number(y)-1),priorDonors=new Set(rows.filter(g=>year(g.date)===yearBefore).map(g=>g.donorId)),retained=[...priorDonors].filter(id=>thisYear.some(g=>g.donorId===id)).length,retention=priorDonors.size?Math.round(retained/priorDonors.size*100):null,byType=t=>sum(thisYear.filter(g=>g.type===t)),monthValue=sum(rows.filter(g=>month(g.date)===m)),avg=rows.length?Math.round(sum(rows)/rows.length):0,unique=new Set(rows.map(g=>g.donorId)).size,ltv=unique?Math.round(sum(rows)/unique):0,progress=c===db.meta.currency&&db.meta.monthlyTarget?Math.round(monthValue/Number(db.meta.monthlyTarget)*100):null,alerts=[];
 for(const d of db.donors){if(d.status==='Failed payment')alerts.push(`${d.name}: recurring payment needs review`);if(lapsed(d))alerts.push(`${d.name}: previous donor; consider a respectful re-engagement`);if(d.lastContact&&elapsedDays(d.lastContact,iso())>Number(db.meta.stewardshipDays||90))alerts.push(`${d.name}: stewardship contact due`)}for(const a of db.actions.filter(x=>x.status!=='Completed'&&x.due<=shift(iso(),14)))alerts.push(`${a.activity}: action due ${fmt(a.due)}`);for(const x of db.campaigns.filter(x=>x.start>=iso()&&x.start<=shift(iso(),30)))alerts.push(`${x.name}: campaign begins ${fmt(x.start)}`);
 return `<div class="notice warn">This preview does not process payments, send messages or restrict access by staff role. Use only fictional or non-confidential records.</div><div class="rowhead"><div><span class="eyebrow">Fundraising overview</span><h2>${esc(db.meta.organisation||'Your organisation')} · ${esc(c)}</h2></div><label class="field">Dashboard currency<select id="currency">${selectOptions([...new Set([db.meta.currency,...db.gifts.map(g=>g.currency)])],c)}</select></label></div><div class="grid four">${metric('Received this month',money(monthValue,c))}${metric('Received this year',money(sum(thisYear),c))}${metric('All-time received',money(sum(rows),c))}${metric('Active recurring donors',active().length)}</div><div class="grid four" style="margin:15px 0">${metric('One-time donors',db.donors.filter(d=>d.status==='One-time').length)}${metric('Previous / lapsed donors',previous().length)}${metric('Average gift',money(avg,c),'Per recorded gift')}${metric('Average donor value',money(ltv,c),'Recorded income ÷ unique donors; not a forecast')}</div><div class="grid"><section class="panel"><h3>Monthly income trend</h3>${trend(rows)}<p class="tiny">Received gifts only. No currency conversion is applied.</p></section><section class="panel"><h3>This year by gift type</h3>${[['Recurring',byType('Recurring')],['One-time',byType('One-time')],['Major gift',byType('Major gift')]].map(([n,v])=>`<div class="item"><div class="rowhead"><b>${n}</b><b>${money(v,c)}</b></div><div class="bar"><i style="width:${sum(thisYear)?Math.round(v/sum(thisYear)*100):0}%"></i></div></div>`).join('')}<h3 style="margin-top:18px">Monthly target</h3><p>${money(monthValue,c)} of ${c===db.meta.currency?money(db.meta.monthlyTarget,c):'No target in this currency'} · ${progress===null?'—':`${progress}%`}</p><div class="bar"><i style="width:${Math.min(100,progress||0)}%"></i></div><p>Year-to-date retention: <b>${retention===null?'Not enough history':`${retention}%`}</b> · Prior-year donors who also gave this year.</p></section></div><section class="panel"><h3>Needs attention</h3>${alerts.length?alerts.slice(0,12).map(a=>`<div class="item">${esc(a)}</div>`).join(''):'<p class="empty">No alerts at present.</p>'}</section>`}
function donorRows(rows){return `<div class="tablewrap"><table><thead><tr><th>Donor</th><th>Country</th><th>Giving</th><th>Status</th><th>Last gift</th><th>Next expected</th><th>Total in ${esc(filters.currency)}</th><th>Owner</th><th></th></tr></thead><tbody>${rows.map(d=>`<tr><td><b>${esc(d.name)}</b><br><span class="tiny">${esc(d.interests||'')}</span></td><td>${esc(d.country||'—')}</td><td>${d.amount?`${money(d.amount,d.currency)} / ${esc(d.frequency.toLowerCase())}`:'One-time'}</td><td>${pill(d.status)}</td><td>${fmt(lastGift(d.id))}</td><td>${fmt(d.nextExpected)}</td><td>${money(totalFor(d.id),filters.currency)}</td><td>${esc(d.owner||'—')}</td><td><button class="link" data-act="profile" data-id="${d.id}">Open profile</button></td></tr>`).join('')||'<tr><td colspan="9">No donors match this view.</td></tr>'}</tbody></table></div>`}
function recurringView(){const state=recurringFilter;const rows=db.donors.filter(d=>d.frequency&&(!state||d.status===state));return `<div class="rowhead"><div><span class="eyebrow">Relationships over time</span><h2>Recurring donors</h2><p>Review giving status, preferences and the next expected gift. A failed payment is an action, not a completed gift.</p></div><button class="button" data-act="new-donor">Add donor</button></div><section class="panel"><div class="toolbar"><label class="field">Filter status<select id="recurring-filter">${opt([['','All'],...recurringStates.map(s=>[s,s])],state)}</select></label><button class="button secondary" data-act="add-gift">Record received gift</button></div>${donorRows(rows)}</section>`}
function oneTimeView(){const rows=db.donors.filter(d=>d.status==='One-time'||db.gifts.some(g=>g.donorId===d.id&&g.type==='One-time'));return `<div class="rowhead"><div><span class="eyebrow">First gifts & renewed interest</span><h2>One-time donors</h2><p>Record the gift and receipt, then decide whether a thoughtful recurring invitation is appropriate.</p></div><div class="actions"><button class="button" data-act="new-donor">Add donor</button><button class="button secondary" data-act="add-gift">Record gift</button></div></div><section class="panel">${donorRows(rows)}</section><section class="panel"><h3>Follow-up opportunities</h3>${rows.filter(d=>d.potentialRecurring).map(d=>`<div class="item"><b>${esc(d.name)}</b> · potential recurring supporter · Last gift ${fmt(lastGift(d.id))} <button class="link" data-act="profile" data-id="${d.id}">Plan follow-up →</button></div>`).join('')||'<p class="empty">No one-time donors flagged for recurring follow-up.</p>'}</section>`}
function previousView(){const rows=previous(),recovered=db.donors.filter(d=>d.reactivation==='Reactivated'),contacted=db.donors.filter(d=>['Contacted','Reactivated','Not interested'].includes(d.reactivation));return `<div class="rowhead"><div><span class="eyebrow">Respectful reconnection</span><h2>Previous donors</h2><p>People whose recurring giving stopped, payment failed, or last gift is older than your lapse threshold.</p></div><button class="button secondary" data-act="settings">Set lapse period</button></div><div class="grid three">${metric('Previous / at risk',rows.length)}${metric('Recovery rate',contacted.length?`${Math.round(recovered.length/contacted.length*100)}%`:'—','Reactivated ÷ contacted outcomes')}${metric('Value regained',money(sum(db.gifts.filter(g=>g.currency===(filters.currency==='All'?db.meta.currency:filters.currency)&&recovered.some(d=>d.id===g.donorId&&d.reactivatedAt&&g.date>=d.reactivatedAt))),filters.currency),'Recent gifts from reactivated donors')}</div><section class="panel" style="margin-top:15px"><div class="tablewrap"><table><thead><tr><th>Donor</th><th>Previous amount</th><th>Last gift</th><th>History</th><th>Known reason</th><th>Last contact</th><th>Reactivation</th><th>Suggested next step</th></tr></thead><tbody>${rows.map(d=>`<tr><td><button class="link" data-act="profile" data-id="${d.id}">${esc(d.name)}</button></td><td>${d.amount?money(d.amount,d.currency):'One-time'}</td><td>${fmt(lastGift(d.id))}</td><td>${giftsFor(d.id).length} gifts</td><td>${esc(d.cancellationReason||'Not recorded')}</td><td>${fmt(d.lastContact)}</td><td>${pill(d.reactivation||'Not contacted')}</td><td>${d.status==='Failed payment'?'Offer secure payment update':d.cancellationReason?'Thank them and honour their preference':'Share an impact update or ask for feedback'}</td></tr>`).join('')||'<tr><td colspan="8">No previous donors.</td></tr>'}</tbody></table></div></section>`}
function incomeView(){const c=filters.currency==='All'?db.meta.currency:filters.currency,rows=gifts(),y=year(iso()),periodRows=rows.filter(g=>year(g.date)===y),forecast=active().filter(d=>d.currency===c).reduce((n,d)=>n+Number(d.amount||0)*({Monthly:12,Quarterly:4,Yearly:1}[d.frequency]||0),0),annualPct=c===db.meta.currency&&db.meta.annualTarget?Math.round(sum(periodRows)/Number(db.meta.annualTarget)*100):null;return `<div class="rowhead"><div><span class="eyebrow">Received income only</span><h2>Income & financial overview</h2><p>Use one currency at a time. The browser does not convert currencies or reconcile against a payment processor.</p></div><div class="actions"><button class="button secondary" data-act="add-gift">Record gift</button><button class="button secondary" data-act="campaign">Add campaign</button><button class="button secondary" data-act="export-income">Download Excel</button></div></div><section class="panel"><div class="form no-print">${sel('Currency','currency',['All',...new Set([db.meta.currency,...db.gifts.map(g=>g.currency)])],filters.currency)}${sel('Country','country',['All',...new Set(db.donors.map(d=>d.country))],filters.country)}${sel('Campaign','campaign',['All',...new Set(db.gifts.map(g=>g.campaign).filter(Boolean))],filters.campaign)}${sel('Gift type','type',['All','Recurring','One-time','Major gift'],filters.type)}${field('From date','from',filters.from,'date')}${field('To date','to',filters.to,'date')}</div></section><div class="grid four">${metric('Filtered received',money(sum(rows),c),`${rows.length} gifts`)}${metric('This year',money(sum(periodRows),c))}${metric('Annual target',annualPct===null?'—':`${annualPct}%`,c===db.meta.currency?`${money(sum(periodRows),c)} of ${money(db.meta.annualTarget,c)}`:'No target in this currency')}${metric('Recurring run rate',money(forecast,c),'Active pledges × expected annual frequency; not received income')}</div><div class="grid" style="margin-top:15px"><section class="panel"><h3>Monthly income</h3>${trend(rows)}</section><section class="panel"><h3>Donor growth & gift mix</h3><p><b>New donors this year:</b> ${db.donors.filter(d=>year(d.joined)===y).length}</p><p><b>Recurring gifts:</b> ${money(sum(periodRows.filter(g=>g.type==='Recurring')),c)}</p><p><b>One-time gifts:</b> ${money(sum(periodRows.filter(g=>g.type==='One-time')),c)}</p><p><b>Major gifts:</b> ${money(sum(periodRows.filter(g=>g.type==='Major gift')),c)}</p><p><b>Average gift:</b> ${money(rows.length?sum(rows)/rows.length:0,c)}</p><p><b>Churn snapshot:</b> ${previous().length} previous or at-risk donors / ${db.donors.length} donor records.</p></section></div><section class="panel"><h3>New donors by month</h3>${growthChart()}<p class="tiny">Based on the date joined in each donor profile.</p></section><section class="panel"><h3>Received gift register</h3><div class="tablewrap"><table><thead><tr><th>Date</th><th>Donor</th><th>Amount</th><th>Type</th><th>Campaign / source</th><th>Payment method</th><th>Receipt</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(g=>`<tr><td>${fmt(g.date)}</td><td>${esc(donor(g.donorId)?.name||'Unknown')}</td><td>${money(g.amount,g.currency)}</td><td>${esc(g.type)}</td><td>${esc(g.campaign||'—')}</td><td>${esc(g.method||'—')}</td><td>${esc(g.receipt||'—')}</td></tr>`).join('')||'<tr><td colspan="7">No gifts match these filters.</td></tr>'}</tbody></table></div></section>`}
function actionCard(a){return `<article class="card"><div class="rowhead"><span class="eyebrow">${esc(a.segment||'All supporters')}</span>${pill(a.status)}</div><h3>${esc(a.activity)}</h3><p>${esc(a.objective)}</p><p class="tiny">${esc(a.owner||'No owner')} · Due ${fmt(a.due)} · ${esc(a.priority)} priority</p><div class="bar"><i style="width:${Math.max(0,Math.min(100,Number(a.progress)||0))}%"></i></div><p class="tiny">${esc(a.progress||0)}% complete</p><button class="link" data-act="edit-action" data-id="${a.id}">Open action →</button></article>`}
function campaignBriefs(){return `<section class="panel"><div class="rowhead"><h3>Campaign briefs · analysis → goal → means</h3><button class="button secondary" data-act="campaign">Add campaign</button></div>${db.campaigns.map(c=>`<div class="item"><b>${esc(c.name)}</b> ${pill(c.status)}<p><b>Analysis:</b> ${esc(c.analysis||'Describe the opportunity and what previous giving tells you.')}</p><p><b>Goal:</b> ${esc(c.goalText||`Raise ${money(c.goal,c.currency)} during the campaign.`)}</p><p><b>Means:</b> ${esc(c.means||'Choose channels and messages that fit the audience.')}</p><p class="tiny">${fmt(c.start)}–${fmt(c.end)} · Received ${money(sum(db.gifts.filter(g=>g.campaign===c.name&&g.currency===c.currency)),c.currency)} / target ${money(c.goal,c.currency)}</p><button class="link" data-act="edit-campaign" data-id="${c.id}">Edit brief</button></div>`).join('')||'<p>No campaign briefs yet.</p>'}<details><summary>Outreach quality check</summary><p>Check audience and consent; make the purpose and likely impact clear; use a concise subject and preview; test every link; provide an easy action; agree the sender; prepare a thank-you and update.</p></details></section>`}
function actionPlan(){let actions=db.actions.filter(a=>(period==='Year'&&year(a.due)===year(iso()))||(period==='Quarter'&&year(a.due)===year(iso())&&Math.floor((Number(month(a.due).slice(5))-1)/3)+1===Math.ceil((new Date().getMonth()+1)/3))||(period==='Month'&&month(a.due)===month(iso())));const layout=actionView==='Kanban'?`<div class="kanban">${actionStates.map(s=>`<div class="lane"><h3>${s}</h3>${actions.filter(a=>a.status===s).map(actionCard).join('')||'<p>No actions</p>'}</div>`).join('')}</div>`:actionView==='Calendar'?`<div class="calendar">${[0,1,2,3].map(i=>{const d=new Date();d.setMonth(d.getMonth()+i);const m=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;return `<section class="panel"><h3>${d.toLocaleDateString('en',{month:'long',year:'numeric'})}</h3>${db.actions.filter(a=>month(a.due)===m).map(a=>`<div class="item"><b>${fmt(a.due)}</b><p>${esc(a.activity)}</p><button class="link" data-act="edit-action" data-id="${a.id}">Edit</button></div>`).join('')||'<p>No scheduled actions.</p>'}</section>`}).join('')}</div>`:`<section class="panel tablewrap"><table><thead><tr><th>Goal / strategic objective</th><th>Target group</th><th>What / activity</th><th>Why / how</th><th>When</th><th>Priority</th><th>Owner / budget</th><th>KPI / status</th><th></th></tr></thead><tbody>${actions.map(a=>`<tr><td>${esc(a.objective)}</td><td>${esc(a.segment)}</td><td><b>${esc(a.activity)}</b></td><td>${esc(a.rationale)}<br><span class="tiny">Next: ${esc(a.nextSteps)}</span></td><td>${fmt(a.start)}–${fmt(a.due)}</td><td>${esc(a.priority)}</td><td>${esc(a.owner)}<br>${money(a.budget,db.meta.currency)}</td><td>${esc(a.kpi)}<br>${pill(a.status)}</td><td><button class="link" data-act="edit-action" data-id="${a.id}">Edit</button></td></tr>`).join('')||'<tr><td colspan="9">No actions in this period.</td></tr>'}</tbody></table></section>`;return `<div class="rowhead"><div><span class="eyebrow">From strategy to accountable work</span><h2>Action plan</h2><p>Goal → target group → what → how → when → priority, following the reference campaign matrix. Each action also carries an owner, budget, KPI, evidence, risk and next step.</p></div><button class="button" data-act="new-action">Add action</button></div><div class="toolbar no-print" style="margin-bottom:15px"><label class="field">Planning horizon<select id="action-period">${selectOptions(['Month','Quarter','Year'],period)}</select></label><label class="field">View<select id="action-view">${selectOptions(['Table','Kanban','Calendar'],actionView)}</select></label></div>${layout}<section class="panel"><h3>Upcoming reminders</h3>${db.actions.filter(a=>a.status!=='Completed'&&a.due>=iso()&&a.due<=shift(iso(),30)).sort((a,b)=>a.due.localeCompare(b.due)).map(a=>`<div class="item">${fmt(a.due)} · ${esc(a.activity)} · ${esc(a.owner||'No owner')}</div>`).join('')||'<p>No planned actions in the next 30 days.</p>'}<p class="tiny">Reminders appear here when the tool is opened. Automatic notifications need a connected service.</p></section>${campaignBriefs()}`}
function strategiesView(){return `<div class="rowhead"><div><span class="eyebrow">Gain · retain · maximise</span><h2>Individual giving strategies</h2><p>Adapt the starter approaches and connect each one to a real action. Select a strategy to edit its audience, steps, message and measures.</p></div><button class="button" data-act="new-strategy">Add strategy</button></div>${['Gain','Retain','Maximise'].map(p=>`<section class="panel"><h3>${p} donors ${tip(p==='Gain'?'Help new supporters discover a credible opportunity and make a first gift.':p==='Retain'?'Thank, listen, report back and make giving easy to sustain.':'Offer thoughtful ways for interested supporters to deepen their contribution without pressure.')}</h3><div class="grid">${db.strategies.filter(s=>s.pillar===p).map(s=>`<article class="card strategy-card"><div class="rowhead"><h3>${esc(s.title)}</h3>${pill(s.priority+' priority')}</div><p>${esc(s.why)}</p><details><summary>Implementation guide</summary><p><b>What:</b> ${esc(s.what)}</p><p><b>For:</b> ${esc(s.audience)}</p><p><b>Steps:</b> ${esc(s.steps)}</p><p><b>Message:</b> ${esc(s.message)}</p><p><b>KPI:</b> ${esc(s.kpi)} · <b>Effort:</b> ${esc(s.effort)}</p><p><b>Action plan link:</b> ${esc(db.actions.find(a=>a.id===s.actionId)?.activity||'Not linked')}</p></details><button class="link" data-act="edit-strategy" data-id="${s.id}">Edit strategy →</button></article>`).join('')||'<p class="empty">No strategies in this area.</p>'}</div></section>`).join('')}`}
function journeyView(){const stages=['First contact','First gift','Recurring supporter','Loyal supporter','Ambassador','Major donor'];return `<span class="eyebrow">The relationship over time</span><h2>Donor journey & automations</h2><p>Use these stages to plan communications. Automated messages below are drafts only; this browser preview never sends email or processes payments.</p><div class="journey">${stages.map((s,i)=>`${i?'<span class="arrow">→</span>':''}<div class="card"><span class="eyebrow">0${i+1}</span><h3>${s}</h3></div>`).join('')}</div><section class="panel" style="margin-top:16px"><div class="rowhead"><h3>Workflow library</h3><button class="button" data-act="new-automation">Add workflow</button></div><div class="tablewrap"><table><thead><tr><th>Trigger</th><th>Timing</th><th>Message / action</th><th>Owner</th><th>Status</th><th>Reviewed</th><th></th></tr></thead><tbody>${db.automations.map(a=>`<tr><td>${esc(a.trigger)}</td><td>${esc(a.delay)}</td><td><b>${esc(a.title)}</b><br>${esc(a.message)}</td><td>${esc(a.owner)}</td><td>${pill(a.status)}</td><td>${fmt(a.lastReviewed)}</td><td><button class="link" data-act="edit-automation" data-id="${a.id}">Review / edit</button></td></tr>`).join('')}</tbody></table></div></section><div class="notice warn">Live sending needs a consent-aware email service, payment processor, secure database, authentication and audit logging. Turning a workflow on here only marks the plan as ready; no external message is sent.</div>`}
function reportData(kind){const c=filters.currency==='All'?db.meta.currency:filters.currency,now=iso(),thisMonth=month(now),thisYear=year(now);if(kind==='Monthly fundraising'){const g=db.gifts.filter(x=>x.currency===c&&month(x.date)===thisMonth);return {headers:['Month','Currency','Received gifts','Income','Recurring income','One-time income','Major gift income','Monthly target','Variance'],rows:[[thisMonth,c,g.length,sum(g),sum(g.filter(x=>x.type==='Recurring')),sum(g.filter(x=>x.type==='One-time')),sum(g.filter(x=>x.type==='Major gift')),c===db.meta.currency?db.meta.monthlyTarget:null,c===db.meta.currency?sum(g)-Number(db.meta.monthlyTarget||0):null]]}}if(kind==='Annual income'){const g=db.gifts.filter(x=>x.currency===c&&year(x.date)===thisYear);return {headers:['Year','Currency','Received gifts','Income','Annual target','Variance','Unique donors'],rows:[[thisYear,c,g.length,sum(g),c===db.meta.currency?db.meta.annualTarget:null,c===db.meta.currency?sum(g)-Number(db.meta.annualTarget||0):null,new Set(g.map(x=>x.donorId)).size]]}}if(kind==='Campaign performance')return {headers:['Campaign','Status','Start','End','Goal','Received','Gift count','Currency'],rows:db.campaigns.map(x=>{const g=db.gifts.filter(z=>z.campaign===x.name&&z.currency===x.currency);return[x.name,x.status,x.start,x.end,x.goal,sum(g),g.length,x.currency]})};if(kind==='Donor retention')return {headers:['Donor','Country','Status','First gift','Last gift','Total received','Last contact','Reactivation stage'],rows:db.donors.map(d=>[d.name,d.country,d.status,giftsFor(d.id).map(g=>g.date).sort()[0]||'',lastGift(d.id),totalFor(d.id,c),d.lastContact,d.reactivation])};if(kind==='Donor acquisition')return {headers:['Donor','Country','Joined','First gift','Number of gifts','Total received','Recurring potential'],rows:db.donors.map(d=>[d.name,d.country,d.joined,giftsFor(d.id).map(g=>g.date).sort()[0]||'',giftsFor(d.id).length,totalFor(d.id,c),d.potentialRecurring?'Yes':'No'])};if(kind==='Lapsed donors')return {headers:['Donor','Status','Last gift','Previous amount','Reason','Last contact','Reactivation stage','Owner'],rows:previous().map(d=>[d.name,d.status,lastGift(d.id),d.amount,d.cancellationReason,d.lastContact,d.reactivation,d.owner])};return {headers:['Strategic objective','Activity','Target group','Owner','Due','Budget','KPI','Priority','Status','Progress %','Next step'],rows:db.actions.map(a=>[a.objective,a.activity,a.segment,a.owner,a.due,a.budget,a.kpi,a.priority,a.status,a.progress,a.nextSteps])}}
function reportsView(){const {headers,rows}=reportData(reportKind);return `<div class="rowhead"><div><span class="eyebrow">Share and use your results</span><h2>Reports & export</h2><p>Choose a report, preview the data, then download an editable file or print a PDF.</p></div><div class="actions no-print"><button class="button" data-act="report-xlsx">Download report Excel</button><button class="button secondary" data-act="report-csv">Download report CSV</button><button class="button secondary" data-act="print">Print / save PDF</button></div></div><div class="notice warn">These records are fictional. This browser preview cannot enforce staff permissions or safely store personal donor information.</div><section class="panel"><div class="toolbar no-print"><label class="field">Report<select id="report-kind">${selectOptions(['Monthly fundraising','Annual income','Campaign performance','Donor retention','Donor acquisition','Lapsed donors','Action-plan progress'],reportKind)}</select></label><button class="button secondary" data-act="full-xlsx">Download full workbook</button><label class="button secondary">Import backup JSON<input id="import-json" type="file" accept=".json,application/json" hidden></label><button class="button secondary" data-act="settings">Targets & settings</button></div><span class="eyebrow">Mission & Method · ${esc(db.meta.organisation||'Organisation')}</span><h3>${esc(reportKind)}</h3><p>Generated ${fmt(iso())} · Currency: ${esc(filters.currency)}</p><div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${headers.length}">No records in this report.</td></tr>`}</tbody></table></div></section><p class="tiny">For actual donor records, connect secure accounts, consent controls, audit logs, payment processing and email integration before use.</p>`}
function dialog(title,body){return `<div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalbox"><div class="rowhead"><h2>${esc(title)}</h2><button class="button secondary" data-act="close">Close</button></div>${body}</div></div>`}
function donorForm(d){return `<form class="form" data-form="donor" data-id="${esc(d?.id||'')}">${field('Name','name',d?.name||'','text','required')}${field('Email · sample only','email',d?.email||'','email')}${field('Country','country',d?.country||'')}${field('Date joined','joined',d?.joined||iso(),'date')}${sel('Giving status','status',[...recurringStates,'One-time'],d?.status||'Active')}${field('Recurring amount','amount',d?.amount||0,'number','min="0" step="0.01"')}${field('Currency','currency',d?.currency||db.meta.currency)}${sel('Frequency','frequency',[['','None'],...frequencies.map(s=>[s,s])],d?.frequency||'')}${field('Payment method','paymentMethod',d?.paymentMethod||'')}${sel('Payment status','paymentStatus',['OK','Failed','Unknown'],d?.paymentStatus||'OK')}${field('Next expected gift','nextExpected',d?.nextExpected||'','date')}${field('Last contact','lastContact',d?.lastContact||'','date')}${field('Date reactivated','reactivatedAt',d?.reactivatedAt||'','date')}${field('Relationship owner','owner',d?.owner||'')}${field('Interests / cause area','interests',d?.interests||'')}${sel('Communication preference','preferences',['Quarterly impact update','Monthly update','Campaigns only','No fundraising email'],d?.preferences||'Quarterly impact update')}${sel('Consent record','consent',['Email updates','Contact by phone','No contact consent','Unknown'],d?.consent||'Unknown')}${sel('Reactivation stage','reactivation',reactivationStates,d?.reactivation||'Not contacted')}${sel('Potential recurring donor','potentialRecurring',[['false','No'],['true','Yes']],String(!!d?.potentialRecurring))}${area('Reason for pause / cancellation','cancellationReason',d?.cancellationReason||'')}${area('Relationship notes · no sensitive information','notes',d?.notes||'')}<button class="button" type="submit">Save donor</button></form>`}
function giftForm(g){return `<form class="form" data-form="gift" data-id="${esc(g?.id||'')}">${sel('Donor','donorId',db.donors.map(d=>[d.id,d.name]),g?.donorId||selectedDonor||db.donors[0]?.id||'')}${field('Date received','date',g?.date||iso(),'date','required')}${field('Amount received','amount',g?.amount||'','number','required min="0.01" step="0.01"')}${field('Currency','currency',g?.currency||db.meta.currency)}${sel('Gift type','type',['Recurring','One-time','Major gift'],g?.type||'One-time')}${sel('Campaign / source','campaign',[['','None'],...db.campaigns.map(c=>[c.name,c.name])],g?.campaign||'')}${field('Payment method','method',g?.method||'')}${sel('Receipt status','receipt',['Not sent','Sent','Not required'],g?.receipt||'Not sent')}<p class="tiny">Record only gifts actually received. A pledge or failed payment belongs in the donor profile, not this register.</p><button class="button" type="submit">Save received gift</button></form>`}
function activityForm(x){return `<form class="form" data-form="activity">${sel('Donor','donorId',db.donors.map(d=>[d.id,d.name]),selectedDonor||db.donors[0]?.id||'')}${field('Date','date',iso(),'date')}${sel('Activity','type',['Email','Thank-you','Call','Campaign involvement','Note','Impact update'],x?.type||'Note')}${field('Owner','owner',x?.owner||'')}${area('What happened · no sensitive information','note',x?.note||'')}<button class="button" type="submit">Record activity</button></form>`}
function campaignForm(c){return `<form class="form" data-form="campaign" data-id="${esc(c?.id||'')}">${field('Campaign name','name',c?.name||'','text','required')}${field('Start date','start',c?.start||iso(),'date')}${field('End date','end',c?.end||iso(),'date')}${field('Target','goal',c?.goal||0,'number','min="0"')}${field('Currency','currency',c?.currency||db.meta.currency)}${area('Analysis / opportunity','analysis',c?.analysis||'')}${area('Campaign goal / donor change','goalText',c?.goalText||'')}${area('Means / channels','means',c?.means||'')}${sel('Status','status',['Planned','Active','Completed'],c?.status||'Planned')}<button class="button" type="submit">Save campaign</button></form>`}
function actionForm(a){return `<form class="form" data-form="action" data-id="${esc(a?.id||'')}">${field('Goal / strategic objective','objective',a?.objective||'','text','required')}${field('What / activity','activity',a?.activity||'','text','required')}${area('Why this matters / rationale','rationale',a?.rationale||'')}${field('Target donor group / segment','segment',a?.segment||'')}${field('How / next steps','nextSteps',a?.nextSteps||'')}${field('Owner','owner',a?.owner||'')}${field('Start date','start',a?.start||iso(),'date')}${field('When / due date','due',a?.due||iso(),'date','required')}${field('Budget','budget',a?.budget||0,'number','min="0"')}${field('KPI / target','kpi',a?.kpi||'')}${sel('Priority','priority',['High','Medium','Low'],a?.priority||'Medium')}${sel('Status','status',actionStates,a?.status||'Planned')}${field('Progress %','progress',a?.progress||0,'number','min="0" max="100"')}${sel('Linked campaign','campaignId',[['','None'],...db.campaigns.map(c=>[c.id,c.name])],a?.campaignId||'')}${field('Evidence / link','evidence',a?.evidence||'','url')}${field('Risk / blocker','risk',a?.risk||'')}<button class="button" type="submit">Save action</button></form>`}
function strategyForm(s){return `<form class="form" data-form="strategy" data-id="${esc(s?.id||'')}">${sel('Pillar','pillar',['Gain','Retain','Maximise'],s?.pillar||'Gain')}${field('Strategy title','title',s?.title||'','text','required')}${area('What it is','what',s?.what||'')}${area('Why it matters','why',s?.why||'')}${field('Who it is for','audience',s?.audience||'')}${area('Steps to implement','steps',s?.steps||'')}${area('Suggested message or communication','message',s?.message||'')}${field('KPI','kpi',s?.kpi||'')}${sel('Cost / effort','effort',['Low','Medium','High'],s?.effort||'Medium')}${sel('Priority','priority',['Low','Medium','High'],s?.priority||'Medium')}${sel('Linked action','actionId',[['','None'],...db.actions.map(a=>[a.id,a.activity])],s?.actionId||'')}<button class="button" type="submit">Save strategy</button></form>`}
function automationForm(a){return `<form class="form" data-form="automation" data-id="${esc(a?.id||'')}">${field('Trigger','trigger',a?.trigger||'','text','required')}${field('When after trigger','delay',a?.delay||'')}${field('Workflow title','title',a?.title||'','text','required')}${field('Team owner','owner',a?.owner||'')}${sel('Planning status','status',['Draft','Ready','Paused'],a?.status||'Draft')}${field('Last reviewed','lastReviewed',a?.lastReviewed||iso(),'date')}${area('Message / checklist for human review','message',a?.message||'')}<button class="button" type="submit">Save workflow plan</button><p class="tiny">Ready means approved for later integration. This preview never sends a message.</p></form>`}
function settingsForm(){const m=db.meta;return `<form class="form" data-form="settings">${field('Organisation name','organisation',m.organisation)}${field('Reporting currency','currency',m.currency)}${field('Monthly target','monthlyTarget',m.monthlyTarget,'number','min="0"')}${field('Annual target','annualTarget',m.annualTarget,'number','min="0"')}${field('Lapse threshold · months','lapseMonths',m.lapseMonths,'number','min="1"')}${field('Stewardship reminder · days','stewardshipDays',m.stewardshipDays,'number','min="1"')}${field('Prepared by','preparedBy',m.preparedBy)}<button class="button" type="submit">Save settings</button></form>`}
function profile(d){const events=[...giftsFor(d.id).map(g=>({date:g.date,text:`${g.type} gift received · ${money(g.amount,g.currency)} · Receipt ${g.receipt}`})),...db.activities.filter(a=>a.donorId===d.id).map(a=>({date:a.date,text:`${a.type}: ${a.note}`}))].sort((a,b)=>b.date.localeCompare(a.date));return dialog(d.name,`<div class="grid"><div class="card"><h3>Relationship</h3><p>${esc(d.country||'—')} · Joined ${fmt(d.joined)} · ${pill(d.status)}</p><p><b>Giving:</b> ${d.amount?`${money(d.amount,d.currency)} ${esc(d.frequency.toLowerCase())}`:'One-time'} · <b>Total recorded:</b> ${money(totalFor(d.id),filters.currency)}</p><p><b>Last gift:</b> ${fmt(lastGift(d.id))} · <b>Next expected:</b> ${fmt(d.nextExpected)}</p><p><b>Payment:</b> ${esc(d.paymentMethod||'—')} · ${esc(d.paymentStatus||'—')}</p><p><b>Interests:</b> ${esc(d.interests||'—')} · <b>Owner:</b> ${esc(d.owner||'—')}</p></div><div class="card"><h3>Care & preferences</h3><p><b>Contact:</b> ${esc(d.preferences||'—')} · <b>Consent:</b> ${esc(d.consent||'—')}</p><p><b>Last contact:</b> ${fmt(d.lastContact)} · <b>Reactivation:</b> ${esc(d.reactivation||'—')}</p><p><b>Cancellation reason:</b> ${esc(d.cancellationReason||'—')}</p><p>${esc(d.notes||'')}</p></div></div><div class="actions" style="margin:15px 0"><button class="button" data-act="edit-donor" data-id="${d.id}">Edit donor</button><button class="button secondary" data-act="add-gift" data-id="${d.id}">Record gift</button><button class="button secondary" data-act="add-activity" data-id="${d.id}">Record contact</button></div><section class="panel"><h3>Donor timeline</h3>${events.map(x=>`<div class="item"><b>${fmt(x.date)}</b> · ${esc(x.text)}</div>`).join('')||'<p>No events yet.</p>'}</section>`)}
const donorCols=['Name','Email','Country','Joined','Amount','Currency','Frequency','Status','Payment method','Payment status','Next expected','Preferences','Consent','Interests','Owner','Reactivation','Reason','Last contact','Potential recurring'];
const donorRowsExport=()=>db.donors.map(d=>[d.name,d.email,d.country,d.joined,d.amount,d.currency,d.frequency,d.status,d.paymentMethod,d.paymentStatus,d.nextExpected,d.preferences,d.consent,d.interests,d.owner,d.reactivation,d.cancellationReason,d.lastContact,d.potentialRecurring?'Yes':'No']);
const giftCols=['Donor','Date','Amount','Currency','Type','Campaign','Payment method','Receipt'];
const giftRowsExport=()=>db.gifts.map(g=>[donor(g.donorId)?.name||'',g.date,g.amount,g.currency,g.type,g.campaign,g.method,g.receipt]);
const actionCols=['Strategic objective','Activity','Rationale','Target group','Owner','Start','Due','Budget','KPI','Status','Progress %','Evidence','Risk','Next steps','Campaign','Priority'];
const actionRowsExport=()=>db.actions.map(a=>[a.objective,a.activity,a.rationale,a.segment,a.owner,a.start,a.due,a.budget,a.kpi,a.status,a.progress,a.evidence,a.risk,a.nextSteps,db.campaigns.find(c=>c.id===a.campaignId)?.name||'',a.priority]);
function xlsx(sheets,name){if(!window.MEALXLSX?.build){notice='Excel export is unavailable in this browser. Use CSV instead.';render();return}download(name,window.MEALXLSX.build(sheets),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}
function exportFull(){xlsx([{name:'Donors',headerRows:[0],rows:[donorCols,...donorRowsExport()]},{name:'Received gifts',headerRows:[0],rows:[giftCols,...giftRowsExport()]},{name:'Action plan',headerRows:[0],rows:[actionCols,...actionRowsExport()]},{name:'Campaigns',headerRows:[0],rows:[['Campaign','Start','End','Goal','Currency','Status'],...db.campaigns.map(c=>[c.name,c.start,c.end,c.goal,c.currency,c.status])]},{name:'Strategies',headerRows:[0],rows:[['Pillar','Title','What','Why','Audience','Steps','Message','KPI','Effort','Priority','Linked action'],...db.strategies.map(s=>[s.pillar,s.title,s.what,s.why,s.audience,s.steps,s.message,s.kpi,s.effort,s.priority,db.actions.find(a=>a.id===s.actionId)?.activity||''])]},{name:'Workflows',headerRows:[0],rows:[['Trigger','Timing','Title','Owner','Status','Message'],...db.automations.map(a=>[a.trigger,a.delay,a.title,a.owner,a.status,a.message])]}],'Mission-and-Method-individual-giving-workbook.xlsx')}
function reportExport(kind){const r=reportData(reportKind),name=`Mission-and-Method-${reportKind.toLowerCase().replaceAll(' ','-')}`;if(kind==='csv')download(name+'.csv',csv([r.headers,...r.rows]),'text/csv;charset=utf-8');else xlsx([{name:reportKind,headerRows:[0],rows:[r.headers,...r.rows]}],name+'.xlsx')}
function open(kind,identifier=''){const d=donor(identifier);if(kind==='profile'&&d)modal=profile(d);else if(kind==='new-donor'||kind==='edit-donor')modal=dialog(d?'Edit donor':'Add donor',donorForm(d));else if(kind==='add-gift')modal=dialog('Record received gift',giftForm());else if(kind==='add-activity')modal=dialog('Record donor contact',activityForm());else if(kind==='new-action'||kind==='edit-action')modal=dialog(identifier?'Edit action':'Add action',actionForm(db.actions.find(a=>a.id===identifier)));else if(kind==='new-strategy'||kind==='edit-strategy')modal=dialog(identifier?'Edit strategy':'Add strategy',strategyForm(db.strategies.find(s=>s.id===identifier)));else if(kind==='new-automation'||kind==='edit-automation')modal=dialog(identifier?'Review workflow':'Add workflow',automationForm(db.automations.find(a=>a.id===identifier)));else if(kind==='settings')modal=dialog('Targets & settings',settingsForm());else if(kind==='campaign'||kind==='edit-campaign')modal=dialog(identifier?'Edit campaign brief':'Add campaign',campaignForm(db.campaigns.find(c=>c.id===identifier)));render()}
function handle(el){const a=el.dataset.act,id=el.dataset.id||'';if(a==='close'){modal='';render();return}if(['profile','new-donor','edit-donor','add-gift','add-activity','new-action','edit-action','new-strategy','edit-strategy','new-automation','edit-automation','settings','campaign','edit-campaign'].includes(a)){if(id)selectedDonor=id;open(a,id);return}if(a==='backup')download('Mission-and-Method-individual-giving-backup.json',JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2),'application/json');if(a==='report-csv')reportExport('csv');if(a==='report-xlsx')reportExport('xlsx');if(a==='full-xlsx'||a==='export-income')exportFull();if(a==='print')window.print()}
function submit(form){const kind=form.dataset.form,d=Object.fromEntries(new FormData(form)),identifier=form.dataset.id||'';if(kind==='donor'){const x=db.donors.find(d=>d.id===identifier)||{id:uid()};Object.assign(x,{...d,amount:Number(d.amount)||0,potentialRecurring:d.potentialRecurring==='true'});if(d.reactivation==='Reactivated'&&!x.reactivatedAt)x.reactivatedAt=iso();if(!identifier)db.donors.push(x);modal='';save('Donor profile saved.');return}if(kind==='gift'){if(!donor(d.donorId)||Number(d.amount)<=0){notice='Choose a donor and enter a positive amount actually received.';render();return}const x={id:uid(),...d,amount:Number(d.amount)};db.gifts.push(x);modal='';save('Received gift recorded; income views updated.');return}if(kind==='activity'){if(!donor(d.donorId)||!d.note.trim())return;db.activities.push({id:uid(),...d});const p=donor(d.donorId);p.lastContact=d.date;modal='';save('Donor timeline updated.');return}if(kind==='campaign'){if(!d.name.trim()||db.campaigns.some(c=>c.id!==identifier&&c.name.toLowerCase()===d.name.trim().toLowerCase())){notice='Enter a unique campaign name.';render();return}const x=db.campaigns.find(c=>c.id===identifier)||{id:uid()};Object.assign(x,{...d,goal:Number(d.goal)||0});if(!identifier)db.campaigns.push(x);modal='';save('Campaign brief saved.');return}if(kind==='action'){if(d.due<d.start){notice='Action due date must not precede its start.';render();return}const x=db.actions.find(a=>a.id===identifier)||{id:uid()};Object.assign(x,{...d,budget:Number(d.budget)||0,progress:Math.min(100,Math.max(0,Number(d.progress)||0))});if(!identifier)db.actions.push(x);modal='';save('Action plan updated.');return}if(kind==='strategy'){const x=db.strategies.find(s=>s.id===identifier)||{id:uid()};Object.assign(x,d);if(!identifier)db.strategies.push(x);modal='';save('Strategy updated.');return}if(kind==='automation'){const x=db.automations.find(a=>a.id===identifier)||{id:uid()};Object.assign(x,d);if(!identifier)db.automations.push(x);modal='';save('Workflow plan saved; no messages were sent.');return}if(kind==='settings'){db.meta={...db.meta,...d,monthlyTarget:Number(d.monthlyTarget)||0,annualTarget:Number(d.annualTarget)||0,lapseMonths:Number(d.lapseMonths)||12,stewardshipDays:Number(d.stewardshipDays)||90};if(filters.currency!==db.meta.currency)filters.currency=db.meta.currency;modal='';save('Settings saved.')}}
async function importBackup(file){try{const x=JSON.parse(await file.text());if(x.version!==1||!x.meta||!Array.isArray(x.donors)||!Array.isArray(x.gifts)||!Array.isArray(x.actions)||!Array.isArray(x.strategies)||!Array.isArray(x.automations))throw Error('Not a valid Individual Giving backup');if(!confirm('Replace all browser data with this backup?'))return;db=x;filters.currency=db.meta.currency;tab='Dashboard';save('Backup restored.')}catch(e){notice=`Import failed: ${e.message}`;render()}}
function render(){root.innerHTML=shell();bind()}
function bind(){root.querySelectorAll('[data-tab]').forEach(x=>x.addEventListener('click',()=>{tab=x.dataset.tab;notice='';modal='';render()}));root.querySelectorAll('[data-act]').forEach(x=>x.addEventListener('click',()=>handle(x)));root.querySelectorAll('[data-form]').forEach(x=>x.addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget)}));root.querySelector('#currency')?.addEventListener('change',e=>{filters.currency=e.target.value;render()});root.querySelector('#recurring-filter')?.addEventListener('change',e=>{recurringFilter=e.target.value;render()});root.querySelector('#action-period')?.addEventListener('change',e=>{period=e.target.value;render()});root.querySelector('#action-view')?.addEventListener('change',e=>{actionView=e.target.value;render()});root.querySelector('#report-kind')?.addEventListener('change',e=>{reportKind=e.target.value;render()});root.querySelectorAll('.form.no-print [name]').forEach(x=>x.addEventListener('change',e=>{filters[e.target.name]=e.target.value;render()}));root.querySelector('#import-json')?.addEventListener('change',e=>{if(e.target.files[0])importBackup(e.target.files[0])})}
let recurringFilter='';render();
})();
